def holebb(g):
    n=len(g)
    cells=[(i,j) for i in range(n) for j in range(len(g[i])) if g[i][j]==8]
    return (min(i for i,j in cells),max(i for i,j in cells),min(j for i,j in cells),max(j for i,j in cells))
